window.RP_SESSION={"id":"S-c863ba4de9c6","messages":[{"id":"RP-0171776","time":"2026-06-07T21:18:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"@레마 캐롤라인 여기 맞아요??","characters":["P-55e987e3c831"]},{"id":"RP-0171777","time":"2026-06-07T21:18:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"넹","characters":["P-fec1db60d51e"]},{"id":"RP-0171778","time":"2026-06-07T21:19:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"ㅋㅋ 수박 빙수 있길래 시켜놨어요. 어디서부터 해요?","characters":["P-55e987e3c831"]},{"id":"RP-0171779","time":"2026-06-07T21:20:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"길드로 돌아가서 짐 정리 하고 식당에 케이크 놓는 시점부터 하죠!","characters":["P-fec1db60d51e"]},{"id":"RP-0171780","time":"2026-06-07T21:20:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"예압","characters":["P-55e987e3c831"]},{"id":"RP-0171781","time":"2026-06-07T21:21:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"...내가 짐 풀자마자 바로 와서 그런데. 사실 나 여기 시설도 잘 모르거든.\"","characters":["P-55e987e3c831"]},{"id":"RP-0171782","time":"2026-06-07T21:22:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"우유 좀 가져올까 하는데. 부엌에 미리 끓여서 식혀둔 게 있으려나?\"","characters":["P-55e987e3c831"]},{"id":"RP-0171783","time":"2026-06-07T21:22:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"식탁에 케이크를 놓고 커팅하다가 문득 생각이 났다는 듯 말합니다.","characters":["P-55e987e3c831"]},{"id":"RP-0171784","time":"2026-06-07T21:22:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"우유 없으면 목맥혀. 이게 또 단맛을 희석해주면서 넘기는 게 좋아서.\"","characters":["P-55e987e3c831"]},{"id":"RP-0171785","time":"2026-06-07T21:22:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 네, 여, 여기 있어요! \"\n\n마침 레마가 우유를 마시려고 준비를 하고 있었다.","characters":["P-fec1db60d51e"]},{"id":"RP-0171786","time":"2026-06-07T21:23:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"아, 있었구나! 좋네.\" 나무잔을 뒤집어서 물기를 털고 식탁에 마저 세팅합니다.","characters":["P-55e987e3c831"]},{"id":"RP-0171787","time":"2026-06-07T21:23:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"여기 우유랑...\"","characters":["P-55e987e3c831"]},{"id":"RP-0171788","time":"2026-06-07T21:24:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마가 주전자에서 나무잔으로 우유를 따른다.","characters":["P-fec1db60d51e"]},{"id":"RP-0171789","time":"2026-06-07T21:24:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"엄청 호화스럽구만. 점심부터 케이크로 때운 느낌이지만.\"","characters":["P-55e987e3c831"]},{"id":"RP-0171790","time":"2026-06-07T21:24:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"접시에 케이크 한조각을 담아 레마쪽에 놔주고 자신도 한조각 놓습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0171791","time":"2026-06-07T21:25:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그, 그러게요. 이렇게 호화로운 식사는 거의 처, 처음이에요. \"\n\n우유와 케이크를 같이 먹으며.","characters":["P-fec1db60d51e"]},{"id":"RP-0171792","time":"2026-06-07T21:25:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"포크도 하나씩 접시위에 올려놓고요.","characters":["P-55e987e3c831"]},{"id":"RP-0171793","time":"2026-06-07T21:26:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"내 말은, 그러니까 이게 골드 단위 스테이크는 아니잖아?\"","characters":["P-55e987e3c831"]},{"id":"RP-0171794","time":"2026-06-07T21:26:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"단맛 포화상태다 이거지.\"","characters":["P-55e987e3c831"]},{"id":"RP-0171795","time":"2026-06-07T21:26:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"케이크 한조각 우걱우걱 먹습니다.,","characters":["P-55e987e3c831"]},{"id":"RP-0171796","time":"2026-06-07T21:26:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"우유도 들이키고요.","characters":["P-55e987e3c831"]},{"id":"RP-0171797","time":"2026-06-07T21:26:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 저는 한 끼에 수 시, 실버씩 써 본 적이 어, 없어요. \"\n\n와. 진짜 맛있다...","characters":["P-fec1db60d51e"]},{"id":"RP-0171798","time":"2026-06-07T21:26:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"오, 그래? 그럼 어디에 쓰는데?\"","characters":["P-55e987e3c831"]},{"id":"RP-0171799","time":"2026-06-07T21:27:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"나도 대부분은 장비값으로 나가지만 말야.\"","characters":["P-55e987e3c831"]},{"id":"RP-0171800","time":"2026-06-07T21:28:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 보통... 화, 화살값이요. 모은 것도 이, 있지만요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-0171801","time":"2026-06-07T21:28:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그리고 어, 얼마 전에 검에 이, 인챈트를 했는데 새, 생각보다 비싸서 할부로 내, 내고 있어요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-0171802","time":"2026-06-07T21:29:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"아, 그래. 아까 활 쏘는 거 보니까 궁수더만. 역시 그렇겠지.\"","characters":["P-55e987e3c831"]},{"id":"RP-0171803","time":"2026-06-07T21:29:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"화살을 직접 만드는 편이... 잠깐, 뭔가 일 얘기같다. 하하. 잠깐 케이크 입에 넣고.\"","characters":["P-55e987e3c831"]},{"id":"RP-0171804","time":"2026-06-07T21:29:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"한입 더 먹고 우물거리죠.","characters":["P-55e987e3c831"]},{"id":"RP-0171805","time":"2026-06-07T21:29:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"케이크 냠냠","characters":["P-fec1db60d51e"]},{"id":"RP-0171806","time":"2026-06-07T21:29:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"우유 호롭","characters":["P-fec1db60d51e"]},{"id":"RP-0171807","time":"2026-06-07T21:31:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"흐으, 길드 들어온 지는 얼마나 됐어? 잘 알아?\"","characters":["P-55e987e3c831"]},{"id":"RP-0171808","time":"2026-06-07T21:31:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 저도 하, 한 달 정도 밖에 아, 안 됐을거에요. \"\n\n얼마더라...","characters":["P-fec1db60d51e"]},{"id":"RP-0171809","time":"2026-06-07T21:32:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"뭐 어쨌든 나보단 잘 알겠네. 뭐 알려달라고 귀찮게 굴진 않을테니 안심하라구.\"","characters":["P-55e987e3c831"]},{"id":"RP-0171810","time":"2026-06-07T21:33:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"잠깐, 취소. 내가 바짓단이라도 잡고 매달리면서 알려달라고 해야하는 쪽인가? 나는 뭐 어떻게든 되겠지~ 라고 생각하고 있었어.\"","characters":["P-55e987e3c831"]},{"id":"RP-0171811","time":"2026-06-07T21:34:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 사실 여, 여기 분들이 정말 치, 친절... \"\n\n들어와서 몇 번 맞았던 기억들을 떠올리며.\n\n\" 애정 많고 조, 좋으신 분들이셔서 적응은 어, 어렵지 않을거에요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-0171812","time":"2026-06-07T21:36:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"음... 그래?\" 잠깐 표정을 읽고 말을 흐리더니, 이내 어깨를 으쓱여보입니다. \"오케이, 그건 됐고... 근데 다들 여기서 자나?\"","characters":["P-55e987e3c831"]},{"id":"RP-0171813","time":"2026-06-07T21:36:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 네. 기숙사 배, 배정 받으셨나요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-0171814","time":"2026-06-07T21:36:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"케이크를 포크로 잘라다가 한조각 찍어 빙글빙글 돌립니다.","characters":["P-55e987e3c831"]},{"id":"RP-0171815","time":"2026-06-07T21:37:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"아니. 흐흐, 뭐 신청해야는걸까?\"","characters":["P-55e987e3c831"]},{"id":"RP-0171816","time":"2026-06-07T21:39:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 아뇨, 아, 아마 남는 맨 끄, 끝 방으로 배정될거에요. \"\n\n케이크 냠냠","characters":["P-fec1db60d51e"]},{"id":"RP-0171817","time":"2026-06-07T21:39:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"아무데나 눕지 뭐. 오늘은 대충 근처 여관에서 자야겠다.\"","characters":["P-55e987e3c831"]},{"id":"RP-0171818","time":"2026-06-07T21:39:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"케이크 묵묵","characters":["P-55e987e3c831"]},{"id":"RP-0171819","time":"2026-06-07T21:40:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"레마는 먹성 좋은 편인가여","characters":["P-55e987e3c831"]},{"id":"RP-0171820","time":"2026-06-07T21:40:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"넹","characters":["P-fec1db60d51e"]},{"id":"RP-0171821","time":"2026-06-07T21:40:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"맨날 요리 지문 하고 있어요","characters":["P-fec1db60d51e"]},{"id":"RP-0171822","time":"2026-06-07T21:41:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 아마 스텔라 씨에게 무, 물어보시면 방 위치를 아, 알려 주실거에요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-0171823","time":"2026-06-07T21:41:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"후우, 누가 누군지도 잘 모르지만... 아, 한조각은 너 먹을래?\"","characters":["P-55e987e3c831"]},{"id":"RP-0171824","time":"2026-06-07T21:42:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"케이크 부스러기를 모아서 입에 털어넣고 우유로 한번 입가심 합니다.","characters":["P-55e987e3c831"]},{"id":"RP-0171825","time":"2026-06-07T21:43:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"이게 우유랑 같이 먹으면 포만감이 엄청나단 말이지. 케이크 자체도 무게감이 꽤 있고...\"","characters":["P-55e987e3c831"]},{"id":"RP-0171826","time":"2026-06-07T21:43:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 조, 좋아요! \"\n\n냠냠. 우유 꿀꺽.","characters":["P-fec1db60d51e"]},{"id":"RP-0171827","time":"2026-06-07T21:43:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"혈당이 쭉쭉 올라서 좀 졸려 보이는 레마.","characters":["P-fec1db60d51e"]},{"id":"RP-0171828","time":"2026-06-07T21:43:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"혈당 스파이크으으으","characters":["P-55e987e3c831"]},{"id":"RP-0171829","time":"2026-06-07T21:44:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"잘 먹는구만.\" 물그러미 먹는 걸 하품하며 봅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0171830","time":"2026-06-07T21:45:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"다 먹었으면 치우고 일어날까?\" 슬며시 물어봅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0171831","time":"2026-06-07T21:46:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 조, 좋아요. \"\n\n맞하품. 식기에 남은 당분까지 다 빨아먹고 나서야 설거지를 하고 접시를 말려 둔다.","characters":["P-fec1db60d51e"]},{"id":"RP-0171832","time":"2026-06-07T21:46:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"다른 쓰래기를 버리고 나무잔도 갖다주죠.","characters":["P-55e987e3c831"]},{"id":"RP-0171833","time":"2026-06-07T21:47:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"식탁도 한번 닦아주고요.","characters":["P-55e987e3c831"]},{"id":"RP-0171834","time":"2026-06-07T21:47:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"다 됐지? 난 이만 여관 잡으러 가볼게. 덕분에 오늘 리프레쉬 잘 했어.\"","characters":["P-55e987e3c831"]},{"id":"RP-0171835","time":"2026-06-07T21:47:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"모-던","characters":["P-55e987e3c831"]},{"id":"RP-0171836","time":"2026-06-07T21:50:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"정리를 끝냈으면 길드 현관을 통해 밖으로 나갑니다.","characters":["P-55e987e3c831"]},{"id":"RP-0171837","time":"2026-06-07T21:51:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"끗? 인가요?","characters":["P-55e987e3c831"]},{"id":"RP-0171838","time":"2026-06-07T21:51:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"좋아요!","characters":["P-fec1db60d51e"]},{"id":"RP-0171839","time":"2026-06-07T21:51:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-fec1db60d51e"]},{"id":"RP-0171840","time":"2026-06-07T21:51:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
